package com.crm.invoice;
import com.crm.invoice.entity.*;import com.crm.invoice.repository.*;import com.crm.invoice.service.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import java.util.*;import java.math.BigDecimal;import java.time.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class InvoiceFollowupPolicyTest {InvoiceRepository invoices;InvoicePaymentRepository payments;ReminderPolicyRepository policies;ReminderTaskRepository tasks;InvoiceReminderRepository history;InvoiceFollowupService service;Invoice row;ReminderPolicy policy;ReminderTask task;
 @BeforeEach void setup(){InvoicePresentationPolicyTest.role("ADMIN");invoices=mock(InvoiceRepository.class);payments=mock(InvoicePaymentRepository.class);policies=mock(ReminderPolicyRepository.class);tasks=mock(ReminderTaskRepository.class);history=mock(InvoiceReminderRepository.class);service=new InvoiceFollowupService(invoices,payments,policies,tasks,history,Clock.fixed(Instant.parse("2026-11-07T12:00:00Z"),ZoneOffset.UTC));row=new Invoice();row.setId(7L);row.setInvoiceNumber("INV");row.setCustomerId("101");row.setStatus("UNPAID");row.setCurrency("TND");row.setTotalAmount(new BigDecimal("100"));row.setDueDate(LocalDate.of(2026,11,1));policy=new ReminderPolicy();policy.setEnabled(true);when(policies.lock()).thenReturn(Optional.of(policy));when(policies.findById(1L)).thenReturn(Optional.of(policy));when(invoices.lockById(7L)).thenReturn(Optional.of(row));when(invoices.findAll(any(Specification.class),any(Pageable.class))).thenReturn(new PageImpl<>(List.of(row)));when(payments.sumForInvoice(7L)).thenReturn(BigDecimal.ZERO);when(tasks.saveAndFlush(any())).thenAnswer(c->{task=c.getArgument(0);task.setId(9L);return task;});when(tasks.findById(9L)).thenAnswer(c->Optional.ofNullable(task));when(policies.saveAndFlush(any())).thenAnswer(c->c.getArgument(0));}@AfterEach void clear(){org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 @Test void policyIsExplicitAndCancelsOldPreparations(){service.configure(new InvoiceFollowupService.Policy(false,2,5,"PHONE","Text"));assertFalse(policy.isEnabled());assertEquals(2,policy.getRevision());verify(tasks).cancelForPolicyChange();}
 @Test void disabledPolicyCannotPrepareAnyTask(){policy.setEnabled(false);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.prepare(0));verifyNoInteractions(invoices);}
 @Test void preparesOnlyOnceForTheSameInvoicePolicyCycle(){assertEquals(1,service.prepare(0));assertEquals(LocalDate.of(2026,11,1),task.getScheduledFor());assertEquals("PREPARED",task.getState());when(tasks.existsByInvoiceIdAndPolicyRevisionAndScheduledFor(any(),anyLong(),any())).thenReturn(true);assertEquals(0,service.prepare(0));verify(tasks,times(1)).saveAndFlush(any());verifyNoInteractions(history);}
 @Test void paidArchivedAndDraftInvoicesDoNotProduceReminders(){for(String status:List.of("PAID","DRAFT","CANCELLED")){row.setStatus(status);assertEquals(0,service.prepare(0));}row.setStatus("UNPAID");row.setArchived(true);assertEquals(0,service.prepare(0));verify(tasks,never()).saveAndFlush(any());}
 @Test void fullyPaidBalanceSuppressesReminderEvenWithInconsistentStatus(){when(payments.sumForInvoice(7L)).thenReturn(new BigDecimal("100"));assertEquals(0,service.prepare(0));}
 @Test void handleRechecksEligibilityAndRecordsManualActionExactlyOnce(){service.prepare(0);service.handle(9L,"Phone call recorded");assertEquals("HANDLED",task.getState());service.handle(9L,"Retry");verify(history,times(1)).saveAndFlush(argThat(r->r.getRecordedBy().equals("42")&&r.getChannel().equals("MANUAL")));}
 @Test void paymentOrPolicyChangeBetweenPrepareAndHandleCancelsWithoutRecording(){service.prepare(0);when(payments.sumForInvoice(7L)).thenReturn(new BigDecimal("100"));service.handle(9L,"Call");assertEquals("CANCELLED",task.getState());verifyNoInteractions(history);}
 @Test void archiveRequiresReliableFullSettlementAndKeepsTheInvoice(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.archive(7L));row.setStatus("PAID");when(payments.sumForInvoice(7L)).thenReturn(new BigDecimal("100"));service.archive(7L);assertTrue(row.isArchived());verify(tasks).cancelForInvoice(7L);verify(invoices,never()).delete(any(Invoice.class));}
 @Test void dueViewKeepsCurrencyOutstandingAndNextDateWithoutInventingTotals(){var page=service.invoices(LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"101",null,false,"OVERDUE",0);assertEquals("100",page.getContent().getFirst().outstanding());assertEquals("TND",page.getContent().getFirst().currency());assertEquals(LocalDate.of(2026,11,1),page.getContent().getFirst().nextReminder());}
 @Test void invalidPoliciesPeriodsAndActionNotesAreRefused(){assertThrows(IllegalArgumentException.class,()->service.configure(new InvoiceFollowupService.Policy(true,-1,0,"SMTP","")));assertThrows(IllegalArgumentException.class,()->service.invoices(LocalDate.of(2026,1,1),LocalDate.of(2027,1,2),null,null,null,"ALL",0));assertThrows(IllegalArgumentException.class,()->service.handle(9L," "));}
}
